#include <bits/stdc++.h>
using namespace std;
#include "config.hpp"
mt19937_64 rng(208196);
double rnd(){return double(rng()>>11)*0x1.0p-53;}
struct Meta{int flip=0,swap=0;array<int,6>var={0,0,0,0,0,0},order={0,1,2,3,4,5};};
vector<int> word(const Meta&m){auto v=prefix;for(int j:m.order){auto&w=heads[m.flip][j][m.var[j]];v.insert(v.end(),w.begin(),w.end());}auto&g=gate[m.flip][m.swap];v.insert(v.end(),g.begin(),g.end());v.insert(v.end(),suffix.begin(),suffix.end());return v;}
struct Grammar{vector<pair<int,int>>rules;vector<int>v;};
int counts[256*256];
Grammar compress(vector<int> seq,double noise){Grammar g;g.v=seq;vector<int> used;while(seq.size()>1){used.clear();for(int i=0;i+1<(int)seq.size();++i){int k=seq[i]*256+seq[i+1];if(!counts[k])used.push_back(k);counts[k]++;}double best=-1;int bp=-1;for(int k:used){double score=counts[k]+noise*rnd();if(score>best){best=score;bp=k;}counts[k]=0;}int a=bp/256,b=bp%256,id=NT+g.rules.size();g.rules.push_back({a,b});vector<int> out;for(int i=0;i<(int)seq.size();++i){if(i+1<(int)seq.size()&&seq[i]==a&&seq[i+1]==b){out.push_back(id);i++;}else out.push_back(seq[i]);}seq=move(out);}return g;}
void output(ostream&o,const Meta&m,const Grammar&g,long long it){o<<"{\"iteration\":"<<it<<",\"nodes\":"<<g.rules.size()<<",\"flip\":"<<m.flip<<",\"swap\":"<<m.swap<<",\"roles\":[";for(int i=0;i<6;i++)o<<(i?",":"")<<m.var[i];o<<"],\"order\":[";for(int i=0;i<6;i++)o<<(i?",":"")<<m.order[i];o<<"],\"word\":[";for(int i=0;i<(int)g.v.size();i++)o<<(i?",":"")<<g.v[i];o<<"],\"rules\":[";for(int i=0;i<(int)g.rules.size();i++)o<<(i?",":"")<<"["<<g.rules[i].first<<","<<g.rules[i].second<<"]";o<<"]}\n";o.flush();}
int main(int argc,char**argv){int limit=argc>1?atoi(argv[1]):1000000;ofstream out("candidates.ndjson");Meta cur;auto g=compress(word(cur),0.9);int best=g.rules.size(),curr=best;vector<pair<Meta,int>>elite;int basin=0;for(long long i=0;i<limit;i++){Meta m=cur;int k=rng()%12;if(k<6)m.var[k]=rng()%heads[m.flip][k].size();else if(k<10)swap(m.order[rng()%6],m.order[rng()%6]);else if(k==10)m.swap^=1;else m.flip^=1;auto seq=word(m);auto gg=compress(seq,(i%7==0)?2.:0.999);for(int trial=0;trial<3;trial++){auto h=compress(seq,0.999);if(h.rules.size()<gg.rules.size())gg=move(h);}int n=gg.rules.size();double temp=0.25+1.*((i%10000)/10000.);if(n<=curr||rnd()<exp((curr-n)/temp)){cur=m;curr=n;}if(n<=68){output(out,m,gg,i);elite.push_back({m,n});}if(n<best){best=n;cerr<<"BEST "<<best<<" iter "<<i<<"\n";output(cerr,m,gg,i);}if(i%10000==9999){cerr<<"iter "<<i<<" best "<<best<<" curr "<<curr<<" elite "<<elite.size()<<"\n";if(!elite.empty()){auto &e=elite[rng()%elite.size()];cur=e.first;curr=e.second;}else cur=Meta();}if(n<=65)break;} }
